# -*- coding: utf-8 -*-
"""
Indonesian translation for TAOG focus tree part 3 (175 entries).
High historical accuracy with terms: Sjahrir, Hatta, Musso, Tan Malaka, Persatuan Perjuangan, Maphilindo, dll.
"""

FOCUS_PART3 = {
    "INS_three_year_plan": "Rencana Tiga Tahun",
    "INS_three_year_plan_desc": "Kita dapat menyusun rencana tiga tahun untuk membangun infrastruktur di seluruh kepulauan dan menghubungkan pulau-pulau.",
    "INS_destroy_pacific_colonialism": "Hancurkan Kolonialisme Pasifik",
    "INS_destroy_pacific_colonialism_desc": "Revolusi mungkin telah berakhir, namun masih ada pertempuran yang harus diperjuangkan. Masih banyak rakyat yang hidup di bawah tirani kolonial tepat di depan pintu kita. Kita tidak boleh berpangku tangan dan berdiam diri, kita harus mengambil tindakan untuk membebaskan mereka dari para penjajah!",
    "INS_rapid_mobilization": "Mobilisasi Cepat",
    "INS_rapid_mobilization_desc": "Setiap negara yang kuat memiliki tentara yang kuat sebagai penopangnya. Jika kita ingin menjadi kekuatan besar regional yang mampu mempertahankan kedaulatan kita, kita harus mulai dengan menjadikan tentara kita jauh lebih kuat daripada saat ini.",
    "INS_greater_indonesia": "Proklamasikan Indonesia Raya",
    "INS_greater_indonesia_desc": "Kemaharajaan kuno Nusantara pernah menyatukan dunia Melayu sebagai satu entitas, satu bangsa. Setelah kita membebaskan Malaya dari tirani kolonial, kita harus meneladani para leluhur kita di Nusantara, memproklamasikan seluruh dunia Melayu sebagai satu bangsa yang bersatu.",
    "INS_secularism": "Sekularisme",
    "INS_secularism_desc": "Indonesia adalah rumah bagi berbagai kalangan dari banyak agama. Mencampuradukkan agama dan politik hanya akan memicu perpecahan, oleh karena itu kita harus melarang partai-partai politik berbasis agama.",
    "INS_integrate_sarekat_islam": "Integrasikan Sarekat Islam",
    "INS_integrate_sarekat_islam_desc": "Partai-partai politik Islam besar memiliki banyak dukungan rakyat. Demi kepentingan terbaik kita, kita harus mengintegrasikan mereka ke dalam pemerintahan.",
    "INS_sjahrirs_continued_tenure": "Kelanjutan Masa Jabatan Sjahrir",
    "INS_sjahrirs_continued_tenure_desc": "Perdana Menteri Sjahrir telah membuktikan dirinya sebagai pemimpin ulung, membimbing kita melewati masa revolusi, memperbaiki perekonomian kita, dan menegakkan demokrasi. Kita harus memilihnya kembali sebagai Perdana Menteri.",
    "INS_unity_in_diversity": "Bhinneka Tunggal Ika",
    "INS_unity_in_diversity_desc": "Selama berabad-abad semboyan Bhinneka Tunggal Ika telah menangkap jiwa kepulauan kita. Semasa revolusi, gagasan ini menjadi seruan pemersatu, mengingatkan bangsa Indonesia bahwa kendati kita berbicara dalam banyak bahasa dan memeluk beragam adat istiadat, kita berdiri bersama sebagai satu bangsa. Kita harus mematri semboyan ini ke dalam konstitusi kita, agar persatuan kita lestari untuk generasi-generasi mendatang.",
    "INS_the_timor_issue": "[INS_timor_issue_scripted_name]",
    "INS_timor_issue_scripted_name_issue": "Masalah Timor",
    "INS_timor_issue_scripted_name_attack": "Serang Timor Timur",
    "INS_the_timor_issue_desc": "[INS_timor_issue_scripted_desc]",
    "INS_timor_issue_scripted_desc_issue": "Timor Timur jelas merupakan wilayah sah Indonesia, dan meski revolusi telah berakhir, wilayah itu masih berada di bawah kekuasaan kolonial. Kita akan mengirim ultimatum kepada [721.OWNER.GetName] menuntut penyerahan segera Timor Timur.",
    "INS_timor_issue_scripted_desc_attack": "Timor Timur jelas merupakan wilayah sah Indonesia. Para pemberontak di pulau itu mungkin mengklaim kemerdekaan, tetapi mereka jelas tidak mewakili seluruh penduduk. Sisa-sisa kolonialisme Portugis harus diintegrasikan ke dalam Republik.",
    "INS_pledge_to_allies": "Ikrar kepada Sekutu",
    "INS_pledge_to_allies_desc": "Kita berada dalam risiko diserang sebagai bagian dari konflik yang meluas di seluruh dunia. Kendati hubungan kita dengan Sekutu sempat goyah, kita telah memantapkan diri sebagai kekuatan Demokrasi di Pasifik dan harus menyelaraskan diri dengan negara-negara demokrasi besar.",
    "INS_mixed_economy_system": "Sistem Ekonomi Campuran",
    "INS_mixed_economy_system_desc": "Indonesia adalah negara yang unik dan tidak akan berkembang di bawah Kapitalisme maupun Komunisme tradisional. Kita harus membangun sistem ekonomi campuran, dengan memadukan unsur-unsur kapitalisme dan komunisme.",
    "INS_social_democracy": "Demokrasi Sosial",
    "INS_social_democracy_desc": "Perekonomian [INS.GetAdjective] telah tumbuh pesat sejak kebijakan ekonomi Sjahrir diterapkan. Kita harus menyatakan Indonesia sebagai negara Sosial Demokrat sejati, dan mengembangkan kebijakan ekonomi masa depan berdasarkan prinsip-prinsip sosial demokrasi.",
    "INS_prime_minister_sjarifuddin": "Perdana Menteri Sjarifuddin",
    "INS_prime_minister_sjarifuddin_desc": "Sjarifuddin adalah calon terbaik bagi Indonesia, kebijakan-kebijakannya yang moderat memungkinkan kompromi antara kaum komunis dan sosialis.",
    "INS_concessions_to_communists": "Konsesi kepada Kaum Komunis",
    "INS_concessions_to_communists_desc": "PKI memiliki sejumlah kursi yang signifikan di parlemen, kita harus memberikan beberapa pos menteri kepada para pemimpin PKI untuk menjamin stabilitas.",
    "INS_sjarifuddin_focus_2": "Ekonomi Ekspor Mandiri",
    "INS_sjarifuddin_focus_2_desc": "Dengan kemerdekaan yang baru kita raih, kita harus meninjau kembali sistem ekonomi ekspor kita dan menata ulangnya sehingga tidak lagi memperhitungkan keuntungan Belanda. Meskipun ekonomi berbasis ekspor masih riskan, kita dapat membuatnya jauh lebih andal dibanding tahun-tahun sebelumnya.",
    "INS_prime_minister_hatta": "Perdana Menteri Hatta",
    "INS_prime_minister_hatta_desc": "Mohammad Hatta, yang dikenal sebagai proklamator revolusi bersama Sukarno, menjabat sebagai Wakil Presiden dan secara umum memiliki kecenderungan lebih demokratis di antara keduanya. Beliau akan menjadi Perdana Menteri yang tepat dan dapat diterima secara kompromi oleh sebagian besar partai politik.",
    "INS_hatta_focus_2": "Langkah Selanjutnya",
    "INS_hatta_focus_2_desc": "Revolusi telah usai, dan kendati beberapa tokoh politik bersikeras bahwa revolusi harus terus berlanjut, suara-suara tersebut sebaiknya diabaikan. Sebaliknya kita harus menatap ke depan, kita harus membangun Indonesia agar generasi masa depan dapat hidup dalam kemakmuran.",
    "INS_hatta_princely_advisors": "Integrasikan Daerah Swapraja",
    "INS_hatta_princely_advisors_desc": "Melalui keberagaman kita menemukan persatuan. Kita telah mendasarkan bangsa ini pada prinsip tersebut, tetapi berakhirnya revolusi memberi tekanan pada gagasan ini karena tiadanya lagi perjuangan bersama. Demi mencegah kebencian dan pemberontakan dari kelompok-kelompok minoritas, kita harus membentuk dewan tambahan di mana para penguasa daerah swapraja memiliki suara langsung dalam politik nasional.",
    "INS_prime_minister_tt": "Pemilihan umum Indonesia pertama telah dilaksanakan",
    "INS_guided_democracy": "Nyatakan Darurat Militer",
    "INS_guided_democracy_desc": "Kini jelas bahwa pembagian kekuasaan melalui pembentukan Komite Nasional adalah sebuah kesalahan dan hanya membuahkan ketidakstabilan. Kita tidak boleh membiarkan hal ini berlanjut kecuali kita menginginkan perang saudara lagi. Kita harus memberlakukan darurat militer dan untuk sementara mengambil alih kendali komite sampai ketertiban dipulihkan.",
    "INS_centralization": "Sentralisasi",
    "INS_centralization_desc": "Kekuasaan akan dipusatkan di Jawa dengan pulau-pulau lain memiliki otonomi terbatas. Semua keputusan harus melalui Jawa untuk menjamin ketertiban dan stabilitas. Presiden akan mengawasi jalannya demokrasi.",
    "INS_abolish_national_committee": "Bubarkan Komite Nasional",
    "INS_abolish_national_committee_desc": "Komite Nasional akan dibubarkan dan digantikan oleh Badan Pekerja yang mengabdi di bawah kepresidenan. Presiden akan menjabat seumur hidup untuk menjaga ketertiban. Badan Pekerja akan diberikan wewenang secara bertahap ketimbang sekaligus.",
    "INS_abolish_national_committee_tt": "Dukungan untuk §Y[ROOT.GetNeutralParty]§! akan ditetapkan menjadi §Y100%§!.",
    "INS_pancasila_achieved": "Pancasila Terwujud",
    "INS_pancasila_achieved_desc": "Ketika kita mendirikan negara ini, ia didasarkan pada lima asas Pancasila: Ketuhanan Yang Maha Esa, Kemanusiaan yang adil dan beradab, Persatuan Indonesia, Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, dan Keadilan sosial bagi seluruh rakyat Indonesia. Meskipun kita belum selalu berhasil beroperasi penuh di bawah prinsip-prinsip ini, kita akhirnya mencapai persatuan yang dicita-citakan oleh asas-asas mula tersebut, dan secara resmi dapat memulai babak berikutnya bagi kemakmuran berkelanjutan Republik kita.",
    "INS_the_co_prosperity_sphere": "Lingkungan Kemakmuran Bersama",
    "INS_the_co_prosperity_sphere_tt": "Membuka keputusan §Y$INS_request_membership$§! dan keputusan §Y$INS_assume_complete_power$§! untuk mengubah ideologi negara dan §Y$INS_sukarno$ menjadi Fasis§!.",
    "INS_the_co_prosperity_sphere_desc": "Kendati ada banyak penentangan terhadap kerja sama dengan pihak Jepang, demi kepentingan terbaik kita di masa-masa penuh gejolak ini adalah bergabung dengan kekuatan yang lebih besar agar mampu teguh melawan Sekutu barat.",
    "INS_strengthen_ins_jap_trade": "Perkuat Perdagangan [ROOT.GetAdjective]-[JAP.GetAdjective]",
    "INS_strengthen_ins_jap_trade_desc": "Kita harus meningkatkan hubungan dagang antara kita dan sekutu baru kita. Jika kita menjual kelebihan sumber daya kita dengan harga yang jauh lebih murah, kita dapat membuktikan keberhargaan kita dan memperoleh posisi tawar lebih tinggi setelah perang.",
    "INS_seek_recognition_of_mal_claims": "Tuntut Pengakuan atas Klaim Melayu Kita",
    "INS_seek_recognition_of_mal_claims_desc": "Malaya dan Borneo Utara adalah serumpun dengan kita, hanya terpisahkan oleh batas kolonial yang semu. Kita harus mengupayakan agar [JAP.GetNameDef] mengakui hak kita atas wilayah ini dan menjanjikannya kepada kita begitu kita berhasil mengalahkan Britania.",
    "INS_demand_northern_malay": "Tuntut Melayu Utara",
    "INS_demand_northern_malay_desc": "Melayu Utara saat ini dikuasai oleh Siam, meskipun secara etnis merupakan orang Melayu. Kita tidak akan mentolerir pihak yang mengaku \"sekutu\" menduduki wilayah kita, kita harus menuntut campur tangan dari Jepang.",
    "INS_siam_agreement": "Perjanjian Siam",
    "INS_siam_agreement_desc": "Siam adalah bangsa yang lemah dan tidak mampu berdiri tegak sendiri. Kita telah membuktikan kemampuan kita kepada Jepang, sementara Siam terus tunduk pada tekanan. Tidak diragukan lagi kita semua akan lebih diuntungkan jika Siam menjadi boneka Indonesia.",
    "INS_local_autonomy": "Otonomi Daerah",
    "INS_local_autonomy_industry_tt": "§Y1§! Pabrik Sipil §Rdicabut§! dari §Y[1051.GetName]§!, §Y[335.GetName]§!, dan §Y[1058.GetName]§!.\n§Y1§! Pabrik Sipil §Gditambahkan§! ke §Y4 negara bagian acak yang dimiliki§!.",
    "INS_local_autonomy_desc": "Banyaknya pulau yang mencakup Indonesia memiliki beragam kebudayaan, bahasa, dan kebutuhan yang berbeda. Tidaklah masuk akal menganggap satu pemerintahan pusat dapat mengawasi semuanya dengan berhasil. Kita akan mulai mereformasi Indonesia menjadi Federasi, di mana setiap provinsi memiliki tingkat otonomi yang signifikan atas dirinya sendiri.",
    "INS_union_of_ins_states": "Persatuan Provinsi [ROOT.GetAdjective]",
    "INS_union_of_ins_states_desc": "Kita harus memberikan otonomi yang lebih besar lagi kepada provinsi-provinsi, mengurangi peran pemerintah federal terutama sebatas urusan antardaerah dan luar negeri. Kita akan memilih Presiden federal baru berdasarkan kehendak provinsi-provinsi. Para penguasa lokal akan bebas membentuk struktur kepemimpinan mereka sendiri sesuai keinginan.",
    "INS_union_of_ins_states_tt": "\nMelepaskan §Y[ATJ.GetName]§!, §Y[BLI.Getname]§!, §Y[SSI.GetName]§!, §Y[TNE.GetName]§!, §Y[POK.GetName]§!, dan §Y[GOW.GetName]§! sebagai §Y$autonomy_taog_indonesian_union_state$§!.",
    "INS_indonesian_inter_province_trade_agreement": "Perjanjian Dagang Antarprovinsi [ROOT.GetAdjective]",
    "INS_indonesian_inter_province_trade_agreement_tt": "Semua negara §YIndonesia§! memperoleh:",
    "INS_indonesian_inter_province_trade_agreement_desc": "Perdagangan antarprovinsi harus cepat dan murah. Kita akan memastikan bahwa membeli dan menjual ke provinsi lain hampir selalu lebih menguntungkan ketimbang ke negara lain, melalui pemotongan pajak perdagangan secara drastis dan pembangunan infrastruktur baru antarwilayah.",
    "INS_expanding_the_union": "Memperluas Persatuan",
    "INS_expanding_the_union_desc": "Rakyat di Borneo Utara telah hidup di bawah tirani terlalu lama. Kita akan memanfaatkan perang gerilya demi memaksa Britania mundur, memungkinkan Brunei, Sabah, dan Kerajaan Sarawak menjadi provinsi-provinsi Indonesia.",
    "INS_expanding_the_union_tt": "Membuka keputusan untuk memulai §YPerang Terbatas§! bagi setiap wilayah bagian yang belum kita kuasai di §YBorneo§!.",
    "INS_dismantle_indonesia": "Bubarkan [ROOT.GetName]",
    "INS_dismantle_indonesia_tt": "§YBubarkan federasi§! dan pilih wilayah bagian mana yang menjadi pusat pemerintahan Anda. Provinsi-provinsi selebihnya akan dimerdekakan.",
    "INS_dismantle_indonesia_desc": "Kita telah mencoba berbagai bentuk pemerintahan dan semuanya berakhir dengan ketidakstabilan. Revolusi telah berakhir, dan penjajah Belanda telah dikalahkan, kita tidak lagi dituntut untuk berdiri bersama sebagai satu front kesatuan. Kita akan membubarkan federasi sepenuhnya, memberikan keleluasaan penuh kepada para Sultan setempat untuk mendirikan negara merdeka mereka sendiri.",
    "INS_all_toward_the_war_effort": "Semua untuk Usaha Perang",
    "INS_all_toward_the_war_effort_desc": "Front Melayu dan [AST.GetAdjective] yang kita pimpin akan menentukan masa depan persatuan Melayu untuk tahun-tahun mendatang. Kita tidak boleh menyia-nyiakan sumber daya apa pun, segalanya harus dicurahkan bagi para prajurit pemberani yang berjuang demi kemerdekaan Melayu.",
    "INS_enact_militarism": "Terapkan Militerisme",
    "INS_enact_militarism_desc": "Kita harus memetik sejumlah pelajaran dari [JAP.GetNameDefCap] dan kebijakan militeristiknya. Mengadopsi prinsip-prinsip serupa akan membawa manfaat besar bagi pemerintahan baru kita.",
    "INS_sukarnos_industrialization": "Perkuat Industri Jawa",
    "INS_sukarnos_industrialization_desc": "Industri di Jawa adalah tulang punggung perekonomian dan militer kita. Semua jalan harus menuju ke Roma.",
    "INS_sukarnos_industrialization2": "Setiap Orang Harus Mengambil Peran",
    "INS_sukarnos_industrialization2_desc": "Upaya perang adalah prioritas nomor satu bangsa ini, dan oleh karenanya menjadi kewajiban utama setiap insan Indonesia untuk berkorban. Kemewahan adalah musuh, kompleks industri militer harus terus berkembang.",
    "INS_japanese_military_lessons": "Pelajaran Militer Jepang",
    "INS_japanese_military_lessons_desc": "Kita harus mempelajari doktrin militer Jepang dan menyesuaikan tentara kita seturut dengannya.",
    "INS_support_tan_malakas_coup": "Dukung Kudeta Tan Malaka",
    "INS_support_tan_malakas_coup_desc": "Sukarno memproklamasikan kemerdekaan kita, tetapi ia terbukti sebagai sosok yang ragu-ragu dan gemar berkompromi diplomatik. Tan Malaka dan Persatuan Perjuangannya menuntut apa yang dituntut oleh rakyat: Merdeka Seratus Persen, tanpa perundingan, tanpa kompromi! Jika Sukarno enggan berjuang demi revolusi secara utuh, maka revolusi harus mencari pemimpin yang berani melakukannya.",
    "INS_minimum_program": "Program Minimum",
    "INS_minimum_program_desc": "Persatuan Perjuangan telah menggariskan tuntutannya: pemerintahan rakyat, tentara rakyat, dan nasionalisasi seluruh perkebunan dan industri milik asing. Kita membutuhkan tokoh-tokoh cakap untuk menjalankan program ini. Njono menyuarakan kepentingan kaum buruh, Setyadjit mewakili para cendekiawan partai. Bersama-sama mereka akan memastikan bahwa revolusi terorganisir dari lantai pabrik hingga ke ruang-ruang kekuasaan.",
    "INS_agrarian_reform": "Reforma Agraria",
    "INS_agrarian_reform_desc": "Selama tiga abad tanah Indonesia telah memperkaya perkebunan-perkebunan milik kaum asing. Kaum tani yang menggarapnya hampir tak pernah mengecap hasil jerih payahnya sendiri. Revolusi yang membiarkan ketidakadilan ini berlanjut bukanlah revolusi sama sekali. Kita akan memastikan tanah jatuh ke tangan mereka yang menggarapnya.",
    "INS_soviet_aid": "Bantuan Soviet",
    "INS_soviet_aid_desc": "Uni Soviet telah mengakui revolusi kita dan siap memberikan pasokan. Apa pun perbedaan pandangan antara program kita dengan Moskow, kita tidak boleh menolak bantuan yang ditawarkan. Kita harus menerima persenjataan tersebut dan terus maju melangkah.",
    "INS_pacific_revolution": "Revolusi Pasifik",
    "INS_pacific_revolution_desc": "Kekuatan kolonial belum sepenuhnya mundur dari Asia, mereka hanya hengkang dari Indonesia. Tatanan lama masih bercokol di wilayah seperti Malaya dan Filipina, dan di setiap tempat itu ada rakyat yang mendambakan pembebasan. Revolusi kita telah memberikan martabat sekaligus kewajiban moral untuk membantu mereka. Kita harus melakukannya.",
    "INS_purge_oppurtunists_tt": "Membuka §Y$INS_launch_revolution$§! di negara-negara dengan dukungan komunis §Y60%§! atau lebih. Negara tempat kita menyulut revolusi akan menjadi §Ynegara boneka§! kita.",
    "INS_purge_oppurtunists": "Pembersihan Kaum Oportunis",
    "INS_purge_oppurtunists_desc": "Musso menghabiskan dua puluh tahun di Moskow belajar menerima perintah. Ia kembali dengan instruksi Soviet di sakunya dan sebuah rencana untuk mengubah republik kita menjadi boneka Komintern. Kita tidak menggulingkan kekuasaan Belanda hanya untuk bersujud di hadapan tuan asing lainnya. Kaum oportunis yang hendak menjual revolusi kita ke Moskow harus diberantas hingga ke akar-akarnya, dan bangsa-bangsa yang kita bebaskan harus berkiblat ke Jakarta, bukan ke Kremlin.",
    "INS_the_maphilindo_speech": "Pidato Maphilindo",
    "INS_the_maphilindo_speech_desc": "Jika orang Betawi dan Banjar sama-sama menjadi orang Indonesia kendati berbeda kebudayaan berkat perjuangan bersama melawan tirani, maka tidak ada alasan orang Melayu dan Filipina tidak bisa bersatu bersama kita. Kita harus menyatukan tanah-tanah ini menjadi satu negara kesatuan yang megah!",
    "INS_the_maphilindo_speech_tt": "Mengizinkan pengklaiman inti (core) dan aneksasi subjek §YMelayu§!",
    "INS_pan_asian_union": "Uni Pan-Asia",
    "INS_pan_asian_union_desc": "Revolusi Pasifik baru saja dimulai, dan posisi kita belum aman. Kita harus berdiri bersama dan bekerja sama untuk melindungi satu sama lain dari kekuatan-kekuatan besar dunia. Bersatu kita teguh.",
    "INS_federation_of_aslia": "Federasi Aslia",
    "INS_federation_of_aslia_trigger_tt": "Telah menyelesaikan keputusan §Y$form_maphilindo$§!.",
    "INS_federation_of_aslia_desc": "Bangsa-bangsa yang telah kita bebaskan tidak perlu berdiri sendiri. Tan Malaka selalu membayangkan sesuatu yang lebih agung daripada satu republik semata: sebuah federasi dari daratan Asia hingga Pasifik, bersatu melawan kekuatan kolonial mana pun yang berani kembali. Kita akan menawarkan mereka keanggotaan penuh di negara kita.",
    "INS_aslia_tt": "Mengizinkan pengklaiman inti (core) dan aneksasi subjek §YPasifik§!",
    "INS_pan_economic_area": "Kawasan Ekonomi Pan-Asia",
    "INS_pan_economic_area_desc": "Kerja sama ekonomi di dalam uni sangat penting demi kemakmuran bersama kita. Kita harus memfasilitasi perdagangan bebas bea antar semua negara anggota guna mengurangi ketergantungan kita pada bangsa-bangsa luar.",
    "INS_pan_economic_area_tt": "Semua anggota faksi yang merupakan subjek dari §Y[ROOT.GetNameDef]§!",
    "INS_musso_ascends": "Kebangkitan Musso",
    "INS_musso_ascends_tt": "Membuka §Y$INS_launch_revolution$§! di negara-negara dengan dukungan komunis §Y30%§! atau lebih. Negara tempat kita menyulut revolusi akan tetap merdeka.",
    "INS_musso_ascends_desc": "Tan Malaka hanyalah seorang pemimpi. Musso membawa apa yang tidak dapat diberikan oleh pemimpi: dukungan penuh dari Uni Soviet dan solidaritas gerakan komunis internasional. Revolusi kita tidak perlu berdiri sendirian.",
    "INS_utilize_comintern_connections": "Manfaatkan Koneksi Komintern",
    "INS_utilize_comintern_connections_desc": "Koneksi Musso dengan para pejabat tinggi Komintern membuat proses bergabung dengan Komintern menjadi mudah. Kita harus mengirimnya ke [SOV.GetNameDef] untuk berunding tanpa menunda lagi.",
    "INS_united_against_japan": "Bersatu Melawan [JAP.GetNameDef]",
    "INS_united_against_japan_desc": "Meskipun tidak ada yang senang berpihak pada Sekutu dan luka batin yang ditinggalkan oleh Belanda belum terlupakan, kita harus untuk sementara waktu mengesampingkan perbedaan demi melawan musuh bersama kita, jika tidak kita berisiko melihat penjajah lain menduduki [ROOT.GetName].",
    "INS_revolutionary_economic_cooperation": "Kerja Sama Ekonomi Revolusioner",
    "INS_revolutionary_economic_cooperation_desc": "Kita telah menyelamatkan jutaan nyawa yang tak lagi hidup di bawah tirani. Sekarang, kita harus membangun bersama. Melalui kerja sama dan perdagangan, kita dapat menempa perekonomian dan bala tentara yang tangguh, melindungi kita dari ancaman kekuatan asing di tahun-tahun mendatang.",
    "INS_revolutionary_economic_cooperation_tt": "Memperoleh §Y$INS_revolutionary_economic_cooperation_modifier$§! yang memberikan:\n§Y4%§! Stabilitas §Yper Negara§! tempat kita telah §Ymemulai revolusi§!\n§Y4%§! Kecepatan Konstruksi §Yper Negara§! tempat kita telah §Ymemulai revolusi§!\n§Y4%§! Perolehan Kekuatan Politik §Yper Negara§! tempat kita telah §Ymemulai revolusi§!\n§Y-4%§! Barang Konsumsi §Yper Negara§! tempat kita telah §Ymemulai revolusi§!\n\nSaat ini kita telah memulai revolusi di §Y[?INS_communist_revolts_succeeded]§! negara.",
    "INS_soviet_economic_integration": "Integrasi Ekonomi Soviet",
    "INS_soviet_economic_integration_desc": "Revolusi telah memberi kita kemerdekaan, tetapi kemerdekaan semata tidak membangun pabrik atau memberi makan rakyat banyak. Uni Soviet menawarkan apa yang tidak sudi diberikan oleh kekuatan kapitalis mana pun: keahlian industri, kredit pembangunan, dan perdagangan dengan syarat yang tidak disertai ikatan kolonial. Kita bodoh jika menolaknya.",
    "INS_the_three_year_plan": "Rencana Tiga Tahun",
    "INS_the_three_year_plan_desc": "Kita akan mencanangkan rencana tiga tahun bagi perekonomian kita, yang akan memandu kita dalam jangka panjang dan memangkas waktu birokrasi.",
    "INS_the_three_year_plan_tt": "§YSemangat Nasional§! akan meningkat sebesar §G1%§! setiap bulan hingga mencapai potensi maksimalnya di §Y26%§!.",
    "INS_realign_export_markets": "Menata Ulang Pasar Ekspor",
    "INS_realign_export_markets_desc": "Kita harus memperkuat hubungan dagang global kita, mengurangi ketergantungan pada segelintir kekuatan besar. Sebaliknya, kita harus menjalin banyak transaksi perdagangan dengan negara-negara serta perusahaan-perusahaan yang lebih kecil.",
    "INS_divert_javanese_education_funding_the_east": "Alihkan Dana Pendidikan Jawa ke Timur",
    "INS_divert_javanese_education_funding_the_east_desc": "Tidak dapat disangkal bahwa bekas penjajah kolonial hanya berinvestasi pada kemajuan Jawa dan wilayah Sumatra yang kaya sumber daya, sembari membiarkan wilayah koloni lainnya terbengkalai. Kita dapat memperbaiki ketidakadilan ini dengan mengalokasikan sebagian anggaran pendidikan Jawa untuk membangun sekolah-sekolah baru di kawasan timur.",
    "INS_eastern_universities": "Universitas Kawasan Timur",
    "INS_eastern_universities_desc": "Dengan membangun perguruan tinggi baru di kawasan timur, pendidikan tinggi akan dapat diakses oleh lebih banyak rakyat, dan para mahasiswa akan didorong untuk merantau dari Jawa guna menuntut ilmu, sehingga mempersempit kesenjangan budaya antara Jawa dan wilayah [ROOT.GetName] lainnya.",
    "INS_eng_treaty_holside_tt": "§Y[ENG.GetNameDefCap]§! akan secara resmi menyatakan keberpihakannya di sisi kita dalam konflik dan memberikan bantuan substansial. Jika perang berakhir dengan kemenangan, §Y[ENG.GetNameDefCap]§! berhak atas Borneo.",
    "INS_eng_treaty_engside_tt": "Kita akan secara resmi bersekutu dengan §Y[HOL.GetNameDefCap]§! dalam konflik Hindia Timur. Jika §Y[HOL.GetNameDefCap]§! menang, kita berhak atas kepemilikan Borneo.",
    "INS_fra_treaty_holside_tt": "§Y[FRA.GetNameDefCap]§! akan secara resmi menyatakan keberpihakannya di sisi kita dalam konflik dan memberikan bantuan substansial. Jika perang berakhir dengan kemenangan, §Y[FRA.GetNameDefCap]§! berhak atas Sumatra timur laut.",
    "INS_fra_treaty_fraside_tt": "Kita akan secara resmi bersekutu dengan §Y[HOL.GetNameDefCap]§! dalam konflik Hindia Timur. Jika §Y[HOL.GetNameDefCap]§! menang, kita berhak atas kepemilikan Sumatra timur laut.",
    "INS_take_batavia_explination_tt": "Jika kita berhasil menduduki seluruh Jawa, kita akan menghancurkan pemerintah kolonial dari dalam dan §Gmemenangkan perang§!. Namun, jika kita tidak berhasil melakukannya dalam waktu §Y730 hari§!, kita akan §Rhancur§!.",
    "INS_we_will_need_another_tt": "Karena kita telah menguasai seluruh Jawa, kita perlu menguasai satu wilayah bagian tambahan di luar Jawa.",
    "INS_centralize_the_state": "Sentralisasi Negara",
    "INS_centralize_the_state_desc": "Dari Sumatra hingga Sulawesi, dari Borneo hingga Bangka, program pembangunan kita telah menghadirkan jalan raya, pabrik, dan pranata pemerintahan ke wilayah-wilayah yang dahulunya hanya dikelola di atas kertas oleh [1058.GetName]. Wilayah-wilayah ini bukan lagi provinsi pedalaman yang terpencil. Mereka adalah [INS.GetNameDefCap].",
    "INS_centralize_the_state_1_tt": "Wilayah bagian prasyarat yang berstatus §Ywilayah inti (core)§!:",
    "INS_centralize_the_state_2_tt": "Wilayah bagian prasyarat yang berstatus §Ybukan wilayah inti§!:",
    "INS_fate_of_de_javasche_bank": "[INS_fate_of_de_javasche_bank_scripted_name]",
    "INS_fate_of_de_javasche_bank_scripted_name_colony": "Nasib De Javasche Bank",
    "INS_fate_of_de_javasche_bank_scripted_name_independent": "Nasib Bank Indonesia",
    "INS_fate_of_de_javasche_bank_desc": "[INS_fate_of_de_javasche_bank_scripted_desc]",
    "INS_fate_of_de_javasche_bank_scripted_desc_colony": "Gulden Hindia Timur terjun bebas sejak depresi melanda, dan De Javasche Bank tidak memiliki sarana untuk membendung kejatuhan tersebut. Kita harus memutuskan cara menstabilkan mata uang kita sebelum sisa-sisa kepercayaan investor menguap seluruhnya.",
    "INS_fate_of_de_javasche_bank_scripted_desc_independent": "Kita mewarisi mata uang yang dilanda krisis. Gulden kolonial lama sudah goyah, dan peralihan ke Rupiah belum mampu menenangkan pasar. Bank Indonesia memerlukan arah kebijakan yang jelas dari pemerintah, atau ekonomi muda kita akan menanggung akibatnya.",
    "INS_finish_the_bauxite_project": "Tuntaskan Proyek Bangka",
    "INS_finish_the_bauxite_project_desc": "Dengan beroperasinya jalan, pelabuhan, dan rel kereta api baru di seluruh Bangka-Belitung, tim survei melaporkan adanya endapan wolfram dan kromium yang melebihi perkiraan awal kita. Pulau-pulau ini akan membuktikan nilai tak ternilainya bagi republik.",
    "INS_australian_contracts": "Kontrak Australia",
    "INS_australian_contracts_desc": "Cadangan karet kita telah tumbuh melampaui kebutuhan domestik. Australia, yang haus akan bahan mentah demi menghidupi industrinya sendiri, merupakan mitra dagang yang sangat alami. Mengamankan kontrak jangka panjang dengan perusahaan-perusahaan Australia akan mendatangkan pendapatan stabil dan memperkokoh posisi kita dalam ekonomi kawasan.",
    "INS_coopereate_with_chinese_businessmen": "Kerja Sama dengan Pedagang Tionghoa",
    "INS_coopereate_with_chinese_businessmen_desc": "Kalangan saudagar kaya dan memiliki jaringan luas telah lama memfasilitasi perdagangan di seantero nusantara. Daripada menyingkirkan jaringan yang telah mapan ini, kita harus merangkul mereka. Modal dan keahlian niaga mereka dapat menjadi sangat berharga untuk menarik perekonomian kita keluar dari keterpurukan.",
    "INS_oil_decisions_unlock_tt": "Membuka keputusan §Y$INS_realign_supply_chains_cat$§! baru untuk menjual §YMinyak§!.",
    "INS_negotiate_new_contracts_unlock_tt": "Membuka keputusan §Y$INS_realign_supply_chains_cat$§! baru.",
    "INS_realign_supply_chains_explain_tt": "Membuka Keputusan §Y$INS_realign_supply_chains_cat$§! untuk menjual sumber daya ke perusahaan swasta dengan kontrak sewa 2 tahun.",
    "INS_negotiate_new_contracts": "Rundingkan Kontrak Baru",
    "INS_negotiate_new_contracts_desc": "Reputasi kita yang kian menanjak sebagai pemasok tepercaya telah membuka pintu-pintu kesempatan yang sebelumnya tertutup. Pembeli-pembeli baru mulai berdatangan, dan kita harus bergerak cepat mengikat mereka dalam perjanjian jangka panjang sebelum para pesaing merebutnya.",
    "INS_all_in_on_rubber": "Fokus Penuh pada Karet",
    "INS_all_in_on_rubber_desc": "Karet adalah komoditas andalan terkuat kita, dan kita berniat memanfaatkannya semaksimal mungkin. Setiap jengkal lahan perkebunan yang tersedia akan dialihkan untuk budidaya karet, dan aparatur ekspor kita ditata ulang untuk memasarkannya lebih cepat dan lebih murah dibanding siapa pun di kawasan ini.",
    "INS_more_market_resources": "Mengatasi Dampak Depresi Besar",
    "INS_more_market_resources_desc": "Dunia mungkin sedang terperosok dalam krisis ekonomi, namun krisis melahirkan peluang bagi mereka yang cukup berani memanfaatkannya. Dengan membanjiri pasar komoditas kita pada harga yang tak tertandingi pesaing, kita memastikan bahwa ketika dunia pulih kembali, produk-produk Indonesia telah memadati setiap etalase dan gudang penyimpanan.",
    "INS_recovering_from_the_great_depression": "Pemulihan dari Depresi Besar",
    "INS_recovering_from_the_great_depression_desc": "Depresi Besar telah membawa dampak yang memporak-porandakan bagi [INS.GetNameDef]. Dengan perekonomian kita yang bertumpu pada ekspor, proteksionisme global telah melumpuhkan kita. Saat perdagangan dunia mulai pulih dan terbuka kembali, kita harus giat mencari pasar-pasar baru serta membangun kembali jalur dagang lama kita.",
    "INS_first_come_first_serve": "Siapa Cepat, Dia Dapat",
    "INS_first_come_first_serve_desc": "Kendati proteksionisme Depresi Besar mulai mereda, lonjakan produksi dan nilai gulden yang terlampau tinggi telah menghancurkan pasar ekspor Belanda, karena mitra dagang lama kita di barat beralih ke Amerika Selatan untuk memenuhi pasokan mereka. Daripada bersusah payah mengejar mereka demi perjanjian baru, kita dapat memanfaatkan ini sebagai peluang memperluas pengaruh ke pasar-pasar baru di Asia.",
    "INS_oil_export": "Peningkatan Ekspor Minyak",
    "INS_oil_export_desc": "Kita akan meningkatkan infrastruktur minyak di Sumatra dan Kalimantan demi mengamankan kesepakatan dagang dengan mitra-mitra baru kita.",
    "INS_increased_trade_with_japan": "Peningkatan Perdagangan dengan Jepang",
    "INS_increased_trade_with_japan_desc": "[JAP.GetNameDefCap] telah menjadi mitra dagang yang kian berharga dan tidak mengecewakan kita. Kita harus merundingkan perjanjian dagang baru untuk memperdalam kerja sama ekonomi antara kedua bangsa kita, serta membantu kita lepas dari bayang-bayang Depresi Besar. Hal ini mungkin membuat gusar sekutu-sekutu kita di Barat, terutama Belanda. Namun, jika kita ingin menentukan nasib kita sendiri, kita wajib mengamankan jalur perdagangan mandiri kita.",
    "INS_asian_trade_investments": "Investasi Perdagangan Asia",
    "INS_asian_trade_investments_desc": "Kehancuran akibat Depresi Besar menyadarkan kita betapa kita terlampau bergantung pada mitra dagang barat jangka panjang kita. Dengan ekonomi yang bertumpu pada ekspor, kini sangat mendesak bagi kita untuk mengembangkan dan memperluas pasar-pasar baru di Asia Tenggara demi menjamin ekonomi kita tidak bergantung pada satu negara mana pun.",
    "INS_asian_trade_investments_tt": "Setiap §Y420§! hari, penalti sumber daya ke pasar dari §YDepresi Besar§! akan §GMembaik§! sebesar §Y5%§! hingga modifier negatif hilang sepenuhnya.",
    "INS_declare_free_trade": "Deklarasikan Perdagangan Bebas",
    "INS_declare_free_trade_desc": "Kita tidak boleh berpihak secara eksklusif kepada satu negara mana pun; kita akan membiarkan mekanisme pasar menentukan secara alami pilihan terbaik bagi [INS.GetNameDef].",
}
